---@type ActivityNightCatHomeDojo
local ActivityNightCatHomeDojo = import("Game.Activity.NightCat.ActivityNightCatHomeDojo")

---@class ActivityNightCatComponent
local ActivityNightCatComponent = Class("ActivityNightCatComponent",ECSComponent)

function ActivityNightCatComponent:__init()
    self.name = "ActivityNightCatComponent"
    ---@type ActivityNightCatHomeDojo
    self._nightCatHomeDojo = ActivityNightCatHomeDojo.New()
    self._activityId       = nil -- 活动id
    self._chapterData      = nil -- 章节数据
