---添加解锁剧情
function ActivityNightCatComponent:AddUnlockPlot(plotId)
    self:GetUnlockPlotInfo()[tostring(plotId)] = 1
end

---添加通关剧情
function ActivityNightCatComponent:AddFinishPlot(plotId)
    local unlockPlotInfo = self:GetUnlockPlotInfo()[tostring(plotId)]
    if checkInt(unlockPlotInfo) == 2 then return end
    self:GetUnlockPlotInfo()[tostring(plotId)] = 2

    local plotVo = CfUtils.GetCfVo(AutoIds.IdSetting2733, "NightCatPlotVo", plotId)
    local plotInfo = self:GetPlotInfo()
    plotInfo[tostring(plotVo.chapter)] = plotVo.regionId
end

---IsPassLevelById 是否通关关卡
---@param questId string 关卡id 
function ActivityNightCatComponent:IsPassLevelById(questId)
    local plotVo = CfUtils.GetCf(AutoIds.IdSetting2733, "NightCatPlotVo", true)
    for i, v in ipairs(plotVo) do
        if checkInt(v.regionId) == checkInt(questId) then
            return checkInt(self:GetUnlockPlotInfo()[tostring(v.id)]) == 2
        end
    end
    return false
end

