function ActivityNightCatComponent:StartTimeDown()
    self:ReleaseTimer()
    self._timer = CDTimerModule:AddCD(1, function(count, id, Elapsed)
        --printInfo(checkString(self._nightCatHomeDojo.nextHpSeconds))
        if self._nightCatHomeDojo.climbingResetNum >= self._nightCatHomeDojo.limit then
            self._nightCatHomeDojo.nextHpSeconds = 0
            self:ReleaseTimer()
            return
        end
        if self._nightCatHomeDojo.nextHpSeconds < 0 then
            self._nightCatHomeDojo.climbingResetNum = self._nightCatHomeDojo.climbingResetNum + 1
            self._nightCatHomeDojo.nextHpSeconds = self._nightCatHomeDojo.recoverSeconds
            Events.Broadcast(Constants.EventNames.ActivityNightCatResetRecover)
        end
        self._nightCatHomeDojo.nextHpSeconds = self._nightCatHomeDojo.nextHpSeconds - Elapsed
    end, CountDownTime, true, true)
end

function ActivityNightCatComponent:ReleaseTimer()
    if self._timer then
        CDTimerModule:RemoveCD(self._timer)
        self._timer = nil
    end
end

function ActivityNightCatComponent:RefreshResetInfo(jsonData)
    self._nightCatHomeDojo.climbingResetNum = checkNumber(jsonData.climbingResetNum)
    self._nightCatHomeDojo.limit = checkNumber(jsonData.limit)
    self._nightCatHomeDojo.nextHpSeconds = checkNumber(jsonData.nextHpSeconds)
    self._nightCatHomeDojo.recoverSeconds = checkNumber(jsonData.recoverSeconds)
end

return ActivityNightCatComponent